CREATE DATABASE IF NOT EXISTS transporte CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE transporte;

CREATE TABLE IF NOT EXISTS Roles (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Permissions (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS RolePermissions (role_id INT,permission_id INT,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES Roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES Permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS Users (id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(100) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,first_name VARCHAR(50) NOT NULL,last_name VARCHAR(50) NOT NULL,phone_number VARCHAR(20),is_active TINYINT(1) DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,role_id INT,document_type VARCHAR(50) NOT NULL,document_number VARCHAR(50) NOT NULL UNIQUE,FOREIGN KEY(role_id) REFERENCES Roles(id));
CREATE TABLE IF NOT EXISTS Clients (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,user_type VARCHAR(50) NOT NULL,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS Drivers (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,license_number VARCHAR(50) NOT NULL UNIQUE,license_type VARCHAR(50) NOT NULL,license_expiry_date DATE NOT NULL,FOREIGN KEY(user_id) REFERENCES Users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS Vehicles (id INT AUTO_INCREMENT PRIMARY KEY,plate_number VARCHAR(20) NOT NULL UNIQUE,brand VARCHAR(50) NOT NULL,model VARCHAR(50) NOT NULL,year INT NOT NULL,capacity INT NOT NULL,status ENUM('ACTIVE','MAINTENANCE','INACTIVE') DEFAULT 'ACTIVE',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Routes (id INT AUTO_INCREMENT PRIMARY KEY,origin VARCHAR(100) NOT NULL,destination VARCHAR(100) NOT NULL,distance_km DECIMAL(10,2) NOT NULL,estimated_duration INT NOT NULL,is_active TINYINT(1) DEFAULT 1,price DECIMAL(10,2) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS RouteSchedules (id INT AUTO_INCREMENT PRIMARY KEY,route_id INT NOT NULL,date DATE NOT NULL,time TIME NOT NULL,vehicle_id INT NOT NULL,FOREIGN KEY(route_id) REFERENCES Routes(id),FOREIGN KEY(vehicle_id) REFERENCES Vehicles(id));
CREATE TABLE IF NOT EXISTS DriverSchedules (id INT AUTO_INCREMENT PRIMARY KEY,driver_id INT NOT NULL,route_schedule_id INT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(driver_id) REFERENCES Drivers(id),FOREIGN KEY(route_schedule_id) REFERENCES RouteSchedules(id));
CREATE TABLE IF NOT EXISTS Reservations (id INT AUTO_INCREMENT PRIMARY KEY,client_id INT NOT NULL,route_schedule_id INT NOT NULL,seat_count INT NOT NULL,status ENUM('PENDING','CONFIRMED','CANCELED') DEFAULT 'PENDING',FOREIGN KEY(client_id) REFERENCES Clients(id),FOREIGN KEY(route_schedule_id) REFERENCES RouteSchedules(id));
CREATE TABLE IF NOT EXISTS Sales (id INT AUTO_INCREMENT PRIMARY KEY,reservation_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reservation_id) REFERENCES Reservations(id));
CREATE TABLE IF NOT EXISTS ReservationPassengers (id INT AUTO_INCREMENT PRIMARY KEY,reservation_id INT NOT NULL,first_name VARCHAR(50) NOT NULL,last_name VARCHAR(50) NOT NULL,document_type VARCHAR(50) NOT NULL,document_number VARCHAR(50) NOT NULL UNIQUE,is_client TINYINT(1) DEFAULT 0,FOREIGN KEY(reservation_id) REFERENCES Reservations(id) ON DELETE CASCADE);
